        function changeStatusName(type) {
            var statusId = 0;
            switch (type) {
                case "Draft":
                    statusId = 1;
                    break;
                case "Active":
                    statusId = 2;
                    break;
                case "Inactive":
                    statusId = 3;
                    break;
                case "Template":
                    statusId = 4;
                    break;
                default:
                    statusId = 0;
                    break;
            }
            return statusId;
        };
