        function getNestedChildren(arr, parent) {
            var out = []
            var key = keyList[idex];
            for (var i = 0; i < count; i++) {
                if (arr[i][key] == parent) {

                    if (len > idex + 1)
                        var children = getNestedChildren(arr, arr[i][keyList[idex + 1]], keyList, idex + 1, len)
                    if (children) {
                        arr[i].children = children
                    }

                    out.push(arr[i])
                }
            }

            return out
        }

