        //};
        var groupLink = function (cell, formatterParams, onRendered) {


            return "<a>" + cell.getRow().getData().groupName + "  </a>" +
                "<a href='" + mainService.getBaseUrl() + "#/chatroom/group_chat/" + cell.getRow().getData().groupId + "' title='Start Group Chat'>" +
                "<i class='fa fa-commenting fa-lg'></i></a> ";


        };
        //custom formatter definition
        var arrowIcon = function (cell, formatterParams) {
            cellFormatterBackgroundColor(cell)
            return "<i class='fa fa-chevron-right'></i>";
        };
        //custom formatter definition
        var actionIcon = function (cell, formatterParams) {
            cellFormatterBackgroundColor(cell)
            if (formatterParams.type === 1)
                return '<img src="assets/images/settings.png" width="20">';
            else
                return '<i class="fa fa-cogs" aria-hidden="true"></i>';
        };
        var groupIcon = function (cell, formatterParams, onRendered) {

            cellFormatterBackgroundColor(cell)
            if (cell.getRow().getData().groupIcon != null) {
                var a = [];
                a = cell.getRow().getData().groupIcon.split('/');
                if (a.length < 6) {
                    return "<img class='rounded-circle profile ml-1' src='newAssets/images/group.png' width='30'>";
                }

                else {
                    var url = $scope.baseurl + a[1] + '/' + a[2] + '/' + a[3] + '/' + a[4] + '/' + a[5];
                    var request = new XMLHttpRequest();
                    request.open('HEAD', url, false);
                    request.send();
                    if (request.status == 200) {
                        $scope.img = true;
                        request.abort();
                        return '<img class="rounded-circle profile ml-1"src="' + $scope.baseurl + a[1] + '/' + a[2] + '/' + a[3] + '/' + a[4] + '/' + a[5] + '" width="' + formatterParams.width + '" height="' + formatterParams.height + '">';
                    }
                    else {
                        $scope.img = false;
                        request.abort();
                        return "<img class='rounded-circle profile ml-1' src='newAssets/images/group.png' width='30'>";
                    }
                    request.abort();

                }
            }
            else {
                return "<img class='rounded-circle profile ml-1' src='newAssets/images/group.png' width='30'>";
            }

            //}
            //if (isNull[2] === 'null') {

            //        return '<img src="' + cell.value+'" width="' + formatterParams.width + '" height="' + formatterParams.height + '">';
            //}
            //else
            //    return '<img src="' + cell.value + '"  style="display:none"   width="' + formatterParams.width + '" height="' + formatterParams.height + '">';

        };
        $scope.setTabulatorGroupBy = function (event, persistenceID, columnName) {
            $("button[name=group-rows]:not(." + columnName + ")").removeClass("col-hide active");

            $("." + columnName).toggleClass("col-hide active");
            //var $tabulator = $('#' + tabulatorID);
            var cookieName = 'tabulator-grouping-' + persistenceID;

            if ($("." + columnName).hasClass("col-hide")) {
                tabulator.setGroupBy(columnName);
                tabulator.clearSort();
                tabulator.setSort(columnName, "asc");
                $.cookie(cookieName, columnName);
            } else {
                $("." + columnName).removeClass("col-hide active");
                tabulator.setGroupBy(null);
                $.cookie(cookieName, "");
            }
            $('#pageActionModal').modal('hide');
            //if (!$(event.target).hasClass('active'))
            //    $(event.target).closest('button').addClass('col-hide active');
            //else
            //    $(event.target).closest('button').removeClass('col-hide active');
        }

