                        ajaxURL: $scope.tabType == 0 ? $scope.currentUrl + "/ManageUserGroup" : $scope.currentUrl + "/GetAssignForms",
                        ajaxConfig: "POST", //ajax HTTP request type
                        ajaxContentType: "json",
