        $scope.imgplaceholder = function (imglink) {
            var url = imglink;
            if (url == undefined || url == "" || url == null) {
                url = "newAssets/images/user_geligulu.png";
            }
            var request = new XMLHttpRequest();
            request.open('HEAD', url, false);
            request.send();
            if (request.status == 200) {
                $scope.imglink = true;
                request.abort();
            }
            else {
                $scope.imglink = false;
                url = "newAssets/images/user_geligulu.png";
                request.abort();
            }
            request.abort();
            return url;
        }
