        function authorize() {
            // var clientId = '8147855457-4mj1foqanlnp98ch3h74mklt927hs6kr.apps.googleusercontent.com';      

            var clientId = '8147855457-ifoffp5daessuit3ue0ucq29f2u9ib24.apps.googleusercontent.com';
            // https://www.googleapis.com/auth/contacts.readonly
            // var scopes = 'https://www.google.com/m8/feeds/';
            var scopes = 'https://www.googleapis.com/auth/contacts.readonly';
            gapi.auth.authorize({ client_id: clientId, scope: scopes, immediate: false }, handleAuthorization);
        }
        function handleAuthorization(authorizationResult) {
            $rootScope.$emit("HideLoading");
            if (authorizationResult && !authorizationResult.error) {
                $.get("https://www.google.com/m8/feeds/contacts/default/thin?alt=json&access_token=" + authorizationResult.access_token + "&max-results=500&v=3.0",
                    function (response) {
                        //process the response here
                        //console.log(response);

                        if (!DataService.isEmpty(response['feed']['entry'])) {
                            var contactListData = response['feed']['entry'];
                            angular.forEach(contactListData, function (item) {
                                if (!DataService.isEmpty(item['gd$email']) && !DataService.isEmpty(item['gd$email'][0]['address'])) {
                                    var temp = {};
                                    temp.contactUserName = item['gd$email'][0]['address'];
                                    $scope.importParam.emailList.push(temp.contactUserName)
                                }
                                else if (!DataService.isEmpty(item['gd$phoneNumber']) && !DataService.isEmpty(item['gd$phoneNumber'][0]['$t'])) {
                                    var temp = {};
                                    var $mob = item['gd$phoneNumber'][0]['$t'],
                                        $num = $mob.replace(/[^\w\s]/gi, '').replace(/ +/g, ''),
                                        $mobile_num = $num.match(/^[0-9]{10}$/) ? $num : $num.substring(0, 10);
                                    temp.contactUserName = $mobile_num.trim();
                                    $scope.importParam.phonenumberList.push(temp.contactUserName)

                                }
                            });
                            console.log($scope.importParam)
                            notifierService.notifyMessage('info', 'Import contact', 'it will take time to import..please wait..');
                            $scope.importContact($scope.importParam);
                        }

                    });
            }
        }
