            $scope.listOfMonths = [];
            const YEARS = () => {
                const years = []
                const dateStart = moment("1980-01-01")
                const dateEnd = moment()
                while (dateStart.format('YYYY') <= dateEnd.format('YYYY')) {
                    years.push(dateStart.format('YYYY'))
                    $scope.listOfYears.push({ "year": dateStart.format('YYYY') });
                    dateStart.add(1, 'year')
                }
                return years
            }
            YEARS();
            $scope.listOfYears = $filter('orderBy')($scope.listOfYears, 'year', true);
            var theMonths = ["January", "February", "March", "April", "May",
                "June", "July", "August", "September", "October", "November", "December"];
            for (var i = 0; i < 12; i++) {
                $scope.listOfMonths.push({ "monthId": i + 1, "name": theMonths[i] });
            }
