        // Initialize pivot table plugin
        function initPivot(mps) {
            function renderers() {
                return $.extend(
                    $.pivotUtilities.renderers,
                    $.pivotUtilities.c3_renderers,
                    //$.pivotUtilities.d3_renderers,
                    $.pivotUtilities.export_renderers,
                );
            }
            var chartWidth = $('#output').innerWidth() - ($('#output').innerWidth() / 4) - 50;
            //console.log(chartWidth);
            if (angular.isDefined(mps))
                $("#output").pivotUI(mps, {
                    renderers: renderers(),
                    rendererOptions: {
                        c3: {
                            size: { width: chartWidth }
                        }
                    }
                });
        }

