        $scope.applyExpand = function (type) {
            showLoader("#output");
            bindPivotWithData();
            if (type == 1) {
                $scope.configExpandBy.expandColumnName = "Checkbox Group";
                //$scope.configExpandBy.expandColumn = $scope.expandFieldName;   
                if ($scope.configExpandBy.tableField != "0" && !DataService.isEmpty($scope.configExpandBy.tableField)) {
                    bindPivotWithTableData();
                    loadPivotWithData();
                    if ($scope.configExpandBy.columnField != "0" && !DataService.isEmpty($scope.configExpandBy.columnField)) {

                    }
                }
            }
            else if (type == 2 && $scope.configExpandBy.tableField != "0" && !DataService.isEmpty($scope.configExpandBy.tableField)) {
                bindPivotWithTableData();
                loadPivotWithData();
            }
            var configSettings = '';
            $.unblockUI();
            //else {
            //    configSettings = $("#output").data("pivotUIOptions");
            //}
            //$("#pivotResult").empty();
            $timeout(function () {
                //$$("pivot").load("../data.json");

                //$scope.currentconfig_id = 0;
                if (!DataService.isEmpty($scope.selectedFormSummaryParam)) {
                    if (!DataService.isEmpty($scope.selectedFormSummaryParam.Id)) {
                        $scope.reBindPivotKanban($scope.defaultFields, $scope.selectedFormSummaryParam.structure, $scope.selectedFormSummaryParam);
                    } else {
                        var currentStructure = $$($scope.pivotID).getStructure();
                        $("#pivotResult").empty();
                        loadPivotKanban($scope.defaultFields, $scope.selectedFormSummaryParam);
                        $timeout(function () {
                            $$($scope.pivotID).setStructure(currentStructure)
                        }, 100);
                    }
                } else {
                    var currentStructure = $$($scope.pivotID).getStructure();
                    $("#pivotResult").empty();
                    $scope.reBindPivotKanban($scope.defaultFields, structures);
                    $timeout(function () {
                        $$($scope.pivotID).setStructure(currentStructure)
                    }, 100);
                }
                // initPivot($scope.defaultFields);
                //$("#output").pivotUI($scope.defaultFields, configSettings, true);
            }, 250);
        };
        $scope.reBindPivotKanban = function (mps, currentStructure, currentConfig) {
            $("#pivotResult").empty();
            $scope.pivotID = "pivot_" + generateUniqueNumber();
            let povitHeight = $(window).height() - 300;
            webix.ui({
                container: "pivotResult",
                cols: [{
                    id: $scope.pivotID,
                    view: "pivot",
                    totalColumn: true,
                    footer: true,
                    height: povitHeight,
                    width: '',
                    columnWidth: 75,
                    format: function (value) {
                        if (!DataService.isEmpty(currentConfig) && !DataService.isEmpty(currentConfig.fixedPlaces))
                            return (value && value != "0" ? parseFloat(value).toFixed(currentConfig.fixedPlaces) : value);
                        else
                            return (value && value != "0" ? parseFloat(value).toFixed(0) : value);
                    },
                    data: mps,
                    separateLabel: true,
                    max: true,
                    structure: currentStructure
                },
                { view: "resizer" }
                ]
            });
            //$timeout(function () {              
            //    $$("pivot").setStructure(currentStructure)
            //}, 450);
        };
        $scope.reset = function (type) {
            //alert('hi')
            if (type == 1) {
                $scope.configExpandBy.expandColumn = "0";
            }
            else if (type == 2) {
                $scope.configExpandBy.tableField = "0";
                $scope.configExpandBy.columnField = "0";
            }
            //$scope.applyExpand(type)
        };
        var formatText = function (cell, formatterParams, onRendered) { //plain text value          
            return "<span>" + cell.getRow().getData().configName + " <span class='pull-right'><a  class='delete-config fa-lg' data-config-name='" + cell.getRow().getData().configName + "' data-config-id='" + cell.getRow().getData().Id + "' title='Delete Config'>" +
                "<i class='fa fa-trash'></i></a>        <a  class='save-config  fa-lg ml-2' data-config-id='" + cell.getRow().getData().Id + "' title='Save Config'><i class='fa fa-save'></i></span>";
        };
