        $scope.init = function () {
            $scope.userDetail = mainService.loginDetails();
            var uidParam = (new Date().getTime()).toString(36);
            //console.log(uidParam)
            $scope.formData = {};
            $scope.uid = uidParam;
            $scope.formData.uid = uidParam;
            $scope.currentUrl = mainService.getCurrentEndPointUrl();

            $scope.defaultPlanDetails = {};
            $scope.defaultPlanDetailsTemp = {};
            $scope.$emit("loadSideBar", 0, 3, 0);


        };

        $scope.parseArr = function (idsArr, arrType) {
            var returnString = "";
            var searchInArr = [];
            if (arrType == "domain")
                searchInArr = domains;
            else
                searchInArr = services;

            //console.log('ids arr is this ');
            //console.log(idsArr);

            angular.forEach(idsArr, function (value, key) {
                //console.log(value);
                if (value != "") {
                    if (returnString == "") {
                        returnString = searchInArr[value];
                    }
                    else
                        returnString += "," + searchInArr[value];
                }

            });

            //console.log('return str' + returnString);
            return returnString;
        }
        $scope.loadPlans = function () {
            $rootScope.$emit("ShowLoading");
            var param = {};
            param.action = 4; // action for planList.
            param.getCurrentPlan = true;// set true form getting user's current plan's info as well.


            mainService.managePlans("ManagePlans", param)
                .then(function (response) {

                    if (response.data != null && angular.isDefined(response.data)) {
                        var data = response.data;
                        if (data.length > 0) {

                            $scope.defaultPlanDetails = _.findWhere(data, { defaultPlan: true });
                            $scope.defaultPlanDetailsTemp = angular.copy(_.findWhere(data, { defaultPlan: true }));

                            angular.forEach($scope.defaultPlanDetails, function (value, key) {
                                var dataRow = value;
                                if (key == "domaintype") {
                                    var domainTypeArr = dataRow.split(',');
                                    dataRow = $scope.parseArr(domainTypeArr, "domain");
                                    $scope.defaultPlanDetails[key] = dataRow;
                                }
                                else if (key == "servicetype") {
                                    var servicetypeArr = dataRow.split(',');
                                    dataRow = $scope.parseArr(servicetypeArr, "service");
                                    $scope.defaultPlanDetails[key] = dataRow;
                                }
                                else {
                                    value = dataRow;
                                }
                            });
                            $scope.onSubmit();
                        }


                    }
                    $timeout(function () {
                        $rootScope.$emit("HideLoading");
                    }, 250);
                    $rootScope.safeApply();

                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });
            $rootScope.$emit("HideLoading");
        };

