        var formStatus = ['', 'Draft', 'Active', 'Inactive', 'Template'];
        var formTypeEditor = function (cell, onRendered, success, cancel) {
            var editor1 = $("<select>");
            editor1.append($('<option>').attr({
                'value': ''
            }).append('')
            );
            $.each(formTypes, function (value, text) {
                editor1.append($('<option>').attr({
                    'value': parseInt(value)
                }).append(text)
                );
            });
            editor1.css({ "padding": "3px", "width": "100%", "box-sizing": "border-box" });
            //Set value of editor to the current value of the cell
            editor1.val(editor1.find('option:contains(' + cell.getValue() + ')').val());
            //onRendered(function () {
            //    editor1.focus();
            //    editor1.css("height", "100%");
            //});

            //when the value has been set, trigger the cell to update
            editor1.on("change blur", function (e) {
                setDropdownHeaderFilter(cell.getField(), editor1.val());
                success(editor1.find('option:selected').text());
            });

            //return the editor element
            return editor1[0];
        };
        var formStatusId = ['Draft', 'Active', 'Inactive', 'Template'];
