        $scope.changeKanbanControl = function (fieldName) {

            var param = {};
            var d_values = fieldName.split('#');
            $scope.kDateField = d_values[0].toString();
            $scope.fieldName = d_values[0].toString() + "#0";
            var selKanban = d_values[0].toString() + "," + $stateParams.formId + "," + d_values[1].toString();
            localStorage.setItem("PersistKanban", selKanban);
            $scope.datebtn = "0";

            if (d_values[1].toString() == "1") {
                $scope.datebtn = "1";
                $scope.bindDatepicker();
                $scope.fieldName = d_values[0].toString() + "#1";
                param.SelectedWeek = "thisweek";
                $scope.SelectedWeek = param.SelectedWeek;
                $scope.calendarSettingForm = "";
                $scope.majorMinor = "";
            }
            else if (d_values[1].toString() == "2") {
                $scope.datebtn = "2";
                $scope.fieldName = d_values[0].toString() + "#2";
                $scope.calendarSettingForm = $scope.kDateField;
                // var i = $scope.K_Controllist.indexOf(fieldName);
                //$scope.majorMinor = $scope.K_Controllist.find(x => x.fieldName === fieldName).majorMinor;
                $scope.calFormId = $scope.K_Controllist.find(x => x.fieldName === fieldName).calFormId;
                $scope.sDate = "";
                $scope.endDate = "";
            }
            else {
                $scope.calendarSettingForm = "";
                $scope.majorMinor = "";
                $scope.datebtn = "0";
                $scope.sDate = "";
                $scope.endDate = "";
            }
            $rootScope.$emit("ShowLoading");

            param.action = 4;
            param.k_contrl = d_values[0].toString();
            $scope.getSelectedFormSettings(param);
            //$scope.getAllRecords(fieldName);
        }
