        $scope.getSelectedFormSettings = function (paramData) {
            $rootScope.$emit("ShowLoading");
            var param = {};
            $scope.kanbanList = [];
            param = paramData;
            param.formId = $scope.currentFormId;
            param.created_by = $scope.userDetail.Id;
            param.update_by = $scope.userDetail.Id;
            $scope.Is_Kanban_Status = false;
            $scope.basicCalendar_active = false;
            mainService.manageForm("ManageForm", param)
                .then(function (response) {

                    if (response.data != null && angular.isDefined(response.data)) {
                        if (response.data.length > 0) {
                            if (param.action == 4) {
                                $scope.importFormSettings = response.data[0];
                                if (($scope.importFormSettings.toDate_field != null && $scope.importFormSettings.fromDate_field != null) && ($scope.importFormSettings.toDate_field != '' && $scope.importFormSettings.fromDate_field != '')) {
                                    $scope.basicCalendar_active = true;
                                }
                                var formData = JSON.parse($scope.importFormSettings.fields);
                                var formDataTemp = [];
                                $scope.K_Controllist = [];
                                var temp = {};
                                var tempData = [];
                                var count = 0;
                                $scope.formReferenceFieldsListFile = [];
                                $scope.formReferenceFieldsList = [];
                                //$timeout(function () {

                                _.each(formData, function (pagesData, key) {
                                    if (!Array.isArray(pagesData))
                                        formData[key] = JSON.parse(pagesData);
                                    _.each(formData[key], function (item) {

                                        temp = {};

                                        if (item.List_column1 == "Yes" && item.types != "Is_Kanban_Status" && item.type != "file") {
                                            temp.fieldName = item.name;
                                            temp.fieldLabel = item.label;
                                            temp.type = item.type;
                                            $scope.formReferenceFieldsList.push(temp);

                                        }
                                        else {
                                            if (item.type == "file") {
                                                temp.fieldName = item.name;
                                                temp.fieldLabel = item.label;
                                                temp.type = item.type;
                                                $scope.formReferenceFieldsListFile.push(temp);
                                            }
                                        }
                                        if (item.types == "Is_Kanban_Status" || (item.type == "date" && item.Use_As_Kanban == "Yes")) {

                                            if ($scope.fieldName == "" && $scope.K_Controllist.length == 0) {
                                                $scope.fieldName = item.name + "#0";
                                                if ((item.type == "date" && item.Use_As_Kanban == "Yes")) {
                                                    $scope.fieldName = item.name + "#1";
                                                }
                                            }
                                            temp.fieldLabel = item.label;
                                            temp.date_btn = "0";
                                            temp.fieldName = item.name + "#0";
                                            if ((item.type == "date" && item.Use_As_Kanban == "Yes")) {
                                                temp.date_btn = "1";
                                                temp.fieldName = item.name + "#1";
                                            }
                                            $scope.K_Controllist.push(temp);

                                        }
                                        if (item.name == param.k_contrl) {
                                            //temp.fieldName = item.name;
                                            temp.fieldLabel = item.label;
                                            if ($scope.kanbanList.length == 0) {
                                                $scope.Is_Kanban_Status = true;

                                                if (!DataService.isEmpty(item.Referral_Forms)) {
                                                    $scope.getKanbanStatusList(item);
                                                }
                                                if ($scope.datebtn == "1") {
                                                    var day_no = 1;
                                                    var e = 0;

                                                    if ($scope.SelectedWeek == "lastweek") {
                                                        e = -1;
                                                    }
                                                    else if ($scope.SelectedWeek == "thisweek") { e = 0; }
                                                    else if ($scope.SelectedWeek == "nextweek") { e = 1; }
                                                    else {
                                                        $scope.SelectedWeek == "customweek"
                                                        e = 2;
                                                    }
                                                    if (e == 0) {
                                                        $rootScope.timeTracker = moment();
                                                    } else {
                                                        $rootScope.timeTracker.add(e, 'weeks');
                                                    }
                                                    // Find start and end of week
                                                    var startOfWeek = $rootScope.timeTracker.clone().startOf('isoWeek');
                                                    var endOfWeek = $rootScope.timeTracker.clone().endOf('isoWeek');
                                                    if (e == 2) {

                                                        startOfWeek = moment($scope.sDate);
                                                        endOfWeek = moment($scope.endDate);
                                                        $scope.startday = startOfWeek.format("M/DD");
                                                        $scope.endday = endOfWeek.format("M/DD");
                                                    }
                                                    else {
                                                        $scope.startday = startOfWeek.format("M/DD");
                                                        $scope.endday = endOfWeek.format("M/DD");
                                                        $scope.sDate = startOfWeek.format("YYYY-MM-DD");
                                                        $scope.endDate = endOfWeek.format("YYYY-MM-DD");
                                                    }
                                                    var days = [];
                                                    var day = startOfWeek;
                                                    var getWeekDate = "";
                                                    while (day.isSameOrBefore(endOfWeek)) {
                                                        days.push(day.toDate());
                                                        var tempValues = {};
                                                        getWeekDate = day.format("YYYY-MM-DD");
                                                        tempValues.header = "<i class='fa fa-plus' indexOrder='" + day_no + "' id='" + $scope.kDateField + "' style='    padding-right: 10px;'></i>  " + day.format('dddd');//+ " <select id='s_orderby'><option>Sorting</option></select>";
                                                        tempValues.name = $scope.kDateField;// moment(weekStart).add(i, 'days').format('dddd');
                                                        tempValues.body = { view: "kanbanlist", status: getWeekDate };
                                                        $scope.kanbanList.push(tempValues);
                                                        day_no++;
                                                        day = day.add(1, 'days');
                                                    }


                                                }

                                                else if (!DataService.isEmpty(item.values)) {
                                                    $scope.kanbanListControlValues = item.values;
                                                    _.each(item.values, function (itmVal, itmKey) {

                                                        var tempValues = {};
                                                        var newRowDesign = [];
                                                        if (!DataService.isEmpty(itmVal)) {
                                                            if (itmVal.value == "" || itmVal.value == null || itmVal.value == undefined) {
                                                                tempValues.header = "Others";
                                                                tempValues.name = item.name;
                                                            }
                                                            else {
                                                                //<span class='webix_icon webix_kanban_add_icon webix_kanban_icon kbi-plus-circle'></span> "
                                                                tempValues.header = "<i class='fa fa-plus' indexOrder='" + itmKey + "' id='" + item.name + "' style='    padding-right: 10px;'></i>         " + itmVal.label;//+ " <select id='s_orderby'><option>Sorting</option></select>";
                                                                //tempValues.header = itmVal.label;
                                                                tempValues.name = item.name;
                                                            }
                                                            //console.log(itmVal.value, 'itmVal.value')
                                                            tempValues.body = { view: "kanbanlist", status: itmVal.value, gravity: 1.3 };

                                                            $scope.kanbanList.push(tempValues);
                                                        }
                                                    });
                                                }
                                            }
                                        }

                                        //item.page = key;
                                        //formDataTemp.push(item);
                                    });
                                });

                                if ($scope.datebtn == "2") {
                                    $scope.getCalenderSettingsFormDetailsData();
                                }
                                else {
                                    $scope.getAllRecords(param.k_contrl, $scope.sDate, $scope.endDate);
                                }

                            }
                            else {
                                notifierService.notifyMessage('success', 'Kanban Form', response.data[0].Message);
                            }

                        }
                    }
                }, function (err) {
                    $rootScope.$emit("HideLoading");
                    console.log("some error occured." + err);
                });

        };

