        $scope.bindDatepicker = function () {

            $("#datecontrol").datetimepicker({

                "format": 'yyyy-mm-dd',
                "assumeNearbyYear": true,
                "autoclose": true,
                "todayBtn": true,
                "todayHighlight": true,
                "minView": 2,
                "viewMode": 'days',
                "pickerPosition": 'bottom-left'
            }).on('changeDate', function (e) {
                console.log('ggg')
                var value = $("#datecontrol").val();
                var firstDate = moment(value, "YYYY-MM-DD").day(0).format("YYYY-MM-DD");
                var lastDate = moment(value, "YYYY-MM-DD").day(6).format("YYYY-MM-DD");
                console.log(firstDate + " - " + lastDate);
                //$scope.fieldName = param.k_contrl + "#0";
                var param = {};
                param.action = 4;
                param.k_contrl = $scope.kDateField;
                $scope.sDate = firstDate;// moment(firstDate);
                $scope.endDate = lastDate;
                $scope.SelectedWeek = "customweek"
                $scope.getSelectedFormSettings(param);
            });
        }
