        function openEntryPage(idex) {

            var newWindow = {};
            var baseUrl = mainService.getBaseUrl();
            var params = windowParams();
            var kanbanControl = {};
            if ($scope.kanbanList.length > 0) {
                if (idex != "" && !DataService.isEmpty(idex)) {
                    kanbanControl = $scope.kanbanList[idex];
                    newWindow = window.open(baseUrl + "#/form/saveEntry/" + $scope.currentFormId + '?popup=1&cname=' + kanbanControl.name + '&value=' + kanbanControl.body.status + '', 'example', params, true);
                } else {
                    newWindow = window.open(baseUrl + "#/form/saveEntry/" + $scope.currentFormId + '?popup=1', 'example', params, true);
                }
                if (!$scope.openAddEntryForm) {
                    $scope.openAddEntryForm = true;
                    var qrString = $location.search();
                    newWindow.focus();
                    var timer = setInterval(function () {
                        if (newWindow.closed) {
                            $scope.openAddEntryForm = false;
                            var qrString = $location.search();
                            //console.log(qrString);
                            var reqType = JSON.parse(localStorage.getItem('detail')).reqType;
                            if (angular.isDefined(qrString.check) && angular.isDefined(reqType)) {
                                var tempUserId = JSON.parse(localStorage.getItem('detail')).name;
                                var date = new Date();
                                date.setTime(date.getTime() + (30 * 1000)); // expires in 30 seconds.
                                $.cookie('tempUserId', tempUserId, { expires: date });
                                localStorage.removeItem('detail');// removing login detais from local storage
                                $state.go("login", { reload: true, inherit: false });
                            }
                            clearInterval(timer);
                            $scope.clearFilter();
                        }
                    }, 500);
                }
                else {
                    newWindow.focus();
                }
            }
        };
