        function bindKanbanImages(data, type) {
            if (!DataService.isEmpty(data)) {
                // console.log(data);
                if (type == 1) {
                    var url = mainService.getBaseUrl() + '/uploadImages/users/' + data.uid + '/profile/' + data.userIcon;
                    var request = new XMLHttpRequest();
                    request.open('HEAD', url, false);
                    request.send();
                    if (request.status == 200) {
                        $scope.img = true;
                        request.abort();
                    }
                    else {
                        $scope.img = false;
                        request.abort();
                        url = mainService.getBaseUrl() + '/newAssets/images/user_geligulu.png';
                    }
                    return url;
                    request.abort();
                }
                else {
                    var url = data;
                    var request = new XMLHttpRequest();
                    request.open('HEAD', url, false);
                    request.send();
                    if (request.status == 200) {
                        $scope.img = true;
                        request.abort();
                    }
                    else {
                        $scope.img = false;
                        request.abort();
                        // url = mainService.getBaseUrl() + '/newAssets/images/broken.png';
                        url = "";
                    }
                    return url;
                    request.abort();
                }
            }
        };
        $scope.convertFormRecordIntoKanbanDataFormat = function () {
            var i = 0;
            $scope.filterFieldsList = [];
            $rootScope.$emit("ShowLoading");
            if ($scope.uniqList != undefined && $scope.uniqList != "" && $scope.uniqList != null) {

                _.each($scope.uniqList, function (item) {
                    var temp = {};
                    temp.id = item.Id;

                    temp.personId = item.Id;
                    temp.value = item.Id;
                    temp.name = item.contactUserName;
                    temp.title = item.contactUserName;
                    temp.image = bindKanbanImages(item, 1);
                    //temp.image = mainService.getBaseUrl() + '/uploadImages/users/' + item.uid + '/profile/' + item.userIcon;
                    $scope.userDataList.push(temp);
                    //console.log('group not empty', $scope.userDataList);
                });
            }
            else {
                var uniqList = _.uniq($scope.formRecordsList, "user_id");
                _.each(uniqList, function (item) {
                    var temp = {};
                    temp.id = item.user_id;
                    temp.personId = item.user_id;
                    temp.value = item.user_id;
                    temp.name = item.username;
                    temp.title = item.username;
                    temp.image = bindKanbanImages(item, 1);
                    //"../uploadImages/users/" + item.uid + "/profile/" + item.userIcon + "";
                    $scope.userDataList.push(temp);
                    //console.log('group empty', $scope.userDataList);
                });
            }
            //console.log('group user', $scope.userDataList);
            if ($scope.formReferenceFieldsListFile.length > 0) {
                $scope.formReferenceFieldsListTemp = $scope.formReferenceFieldsList.slice(0, 9);
                var fileControl = $scope.formReferenceFieldsListFile.slice(0, 1);
                if (!DataService.isEmpty(fileControl))
                    $scope.formReferenceFieldsListTemp.unshift(fileControl[0]);

            } else {
                $scope.formReferenceFieldsListTemp = $scope.formReferenceFieldsList.slice(0, 10);
            }

            _.each($scope.formReferenceFieldsListTemp, function (fieldItem) {
                if (fieldItem.type != "file") {
                    _.every($scope.formRecordsList, function (item) {
                        //console.log(item);
                        item.id = item.Id;
                        if (!DataService.isEmpty(item[fieldItem.fieldName])) {
                            //item[fieldItem.fieldName] = fieldItem.fieldLabel + " : " + item[fieldItem.fieldName]
                            item[fieldItem.fieldName] = item[fieldItem.fieldName];
                            if (i == 0 || i == 1) {
                                item.text += "<h4 style='color:black'>" + item[fieldItem.fieldName] + "</h4> <br> ";
                            }
                            else {
                                item.text += item[fieldItem.fieldName] + " <br> ";
                            }

                            if (!DataService.isEmpty(item.attachments)) {
                                if (!Array.isArray(item.attachments))
                                    if (item.attachments.contains(',')) {
                                        var list = item.attachments.split(',');
                                        var tempList = [];
                                        _.each(list, function (imageList) {
                                            imageList = bindKanbanImages(imageList, 2);
                                            if (!DataService.isEmpty(imageList))
                                                tempList.push({ link: imageList, id: item.Id });
                                        });
                                        item.attachments = tempList;
                                    }
                                    else {

                                        var tempList = [];
                                        item.attachments = bindKanbanImages(item.attachments, 2);
                                        if (!DataService.isEmpty(item.attachments))
                                            tempList.push({ link: item.attachments, id: item.Id });
                                        item.attachments = tempList;

                                    }
                            }
                            return true;
                        }
                    });
                }
                i++;
            });
            $scope.filterFieldsList = $scope.formReferenceFieldsListTemp;
            $scope.filterFieldsList = _.without($scope.filterFieldsList, _.findWhere($scope.filterFieldsList, { type: "file" }));
            //console.log($scope.filterFieldsList, 'filter ');
            $rootScope.safeApply();
        };

